import type { BankQuestion } from "@/lib/bank";

/** Computer Networks (CS Fundamentals): 127 questions. Append new ones at the end with the next id; never reuse or renumber an id. */
const questions: BankQuestion[] = [
  {"id": "cs-computer-networks-1", "question": "In the OSI model, which layer decides the path a packet takes from one network to another?", "options": ["Network layer", "Data link layer", "Transport layer", "Session layer"], "answer": 0, "explanation": "Routing (logical addressing with IP and path selection) is the job of the network layer, layer 3. The data link layer only moves frames across a single link.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-computer-networks-2", "question": "Which protocol finds the MAC address of a host when only its IPv4 address is known?", "options": ["RARP", "ARP", "DNS", "ICMP"], "answer": 1, "explanation": "ARP (Address Resolution Protocol) maps a known IPv4 address to a MAC address on the local network. RARP did the reverse (MAC to IP) and is obsolete.", "difficulty": "easy", "source": "Wipro · Accenture pattern"},
  {"id":"cs-computer-networks-3","question":"What is the well-known TCP port for HTTPS?","options":["80","8080","443","22"],"answer":2,"explanation":"HTTPS (HTTP over TLS) listens on port 443; plain HTTP uses 80, and 22 is SSH.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-computer-networks-4", "question": "The protocol data unit handled at the data link layer is called a:", "options": ["Packet", "Segment", "Bit stream", "Frame"], "answer": 3, "explanation": "Physical layer → bits, data link → frames, network → packets (datagrams), transport → segments (TCP) or datagrams (UDP).", "difficulty": "easy", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-computer-networks-5", "question": "Which device forwards traffic inside a LAN by looking up destination MAC addresses in a table?", "options": ["Switch", "Hub", "Router", "Repeater"], "answer": 0, "explanation": "A switch is a layer-2 device that learns MAC addresses per port and forwards frames only to the right port. A hub just repeats bits to every port; a router works on IP addresses.", "difficulty": "easy", "source": "HCL · Tech Mahindra pattern"},
  {"id": "cs-computer-networks-6", "question": "Which transport-layer protocol is connectionless and gives no delivery guarantee?", "options": ["TCP", "UDP", "SCTP", "HTTP"], "answer": 1, "explanation": "UDP sends independent datagrams with no handshake, acknowledgement or retransmission. TCP is connection-oriented and reliable; HTTP is an application-layer protocol.", "difficulty": "easy", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-7","question":"A subnet uses the mask 255.255.255.240. How many usable host addresses does each subnet have?","options":["15","16","14","30"],"answer":2,"explanation":"240 = 11110000, so 4 host bits remain: 2⁴ = 16 addresses, minus the network and broadcast addresses = 14 usable hosts.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-8","question":"Which of these IPv4 addresses is a private (RFC 1918) address?","options":["11.0.0.1","172.32.1.1","192.169.10.1","172.20.5.4"],"answer":3,"explanation":"Private ranges are 10.0.0.0/8, 172.16.0.0–172.31.255.255 (/12) and 192.168.0.0/16. 172.32.x.x lies just outside the /12 block and 192.169.x.x is outside 192.168/16, a common trap.","difficulty":"easy","source":"Wipro · Accenture pattern"},
  {"id":"cs-computer-networks-9","question":"A newly booted client obtains an IP address through DHCP. In what order are the four DHCP messages exchanged?","options":["Discover → Offer → Request → Acknowledge","Request → Offer → Discover → Acknowledge","Discover → Request → Offer → Acknowledge","Offer → Discover → Acknowledge → Request"],"answer":0,"explanation":"The DORA sequence: the client broadcasts DISCOVER, servers reply with OFFER, the client broadcasts REQUEST for one offer, and the chosen server confirms with ACK.","difficulty":"moderate","source":"Cognizant · Capgemini pattern"},
  {"id":"cs-computer-networks-10","question":"DNS normally carries an ordinary name lookup over which transport, and a zone transfer between DNS servers over which?","options":["TCP port 53 for both","UDP port 53 for lookups; TCP port 53 for zone transfers","UDP port 67 for lookups; TCP port 53 for zone transfers","UDP port 53 for both"],"answer":1,"explanation":"Small queries go over UDP 53 for speed; zone transfers (AXFR) and responses too large for UDP use TCP 53. Port 67 belongs to DHCP.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-11","question":"An HTTP server tells the browser that a page has moved for good to a new URL and that bookmarks should be updated. Which status code does it send?","options":["302 Found","304 Not Modified","301 Moved Permanently","307 Temporary Redirect"],"answer":2,"explanation":"301 is a permanent redirect. 302 and 307 are temporary redirects, and 304 means the cached copy is still valid (no redirect at all).","difficulty":"easy","source":"Product-company MCQ pattern"},
  {"id": "cs-computer-networks-12", "question": "A code must be able to correct any 2-bit error in a codeword. What is the minimum Hamming distance it needs?", "options": ["3", "4", "6", "5"], "answer": 3, "explanation": "To correct t errors the minimum distance must be 2t + 1 = 2(2) + 1 = 5. A distance of 3 corrects only single-bit errors; 4 corrects 1 and detects 3.", "difficulty": "moderate", "source": "HCL · Tech Mahindra pattern"},
  {"id": "cs-computer-networks-13", "question": "What is the maximum throughput (fraction of time the channel carries a successful frame) of pure ALOHA?", "options": ["About 18.4% (1/2e)", "About 36.8% (1/e)", "About 50%", "About 9.2% (1/4e)"], "answer": 0, "explanation": "Pure ALOHA has a vulnerable period of 2 frame times, so S = G·e^(−2G), maximised at G = 0.5 giving 1/(2e) ≈ 0.184. Slotted ALOHA halves the vulnerable period and reaches 1/e ≈ 0.368.", "difficulty": "easy", "source": "Wipro · Accenture pattern"},
  {"id":"cs-computer-networks-14","question":"The ping utility checks whether a host is reachable by sending which kind of message?","options":["TCP SYN segment","ICMP Echo Request","UDP datagram to port 7","ARP request"],"answer":1,"explanation":"ping sends ICMP Echo Request and waits for ICMP Echo Reply. ICMP is carried directly inside IP, with no TCP or UDP port.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-15","question":"How many IPv4 addresses (including network and broadcast) are in the block 160.10.8.0/21?","options":["4096","1024","2048","2046"],"answer":2,"explanation":"A /21 leaves 32 − 21 = 11 host bits, so the block has 2¹¹ = 2048 addresses (2046 usable hosts, which is the trap option).","difficulty":"moderate","source":"Cognizant · Capgemini pattern"},
  {"id":"cs-computer-networks-16","question":"A company with 300 PCs and a single public IPv4 address lets all of them browse the web at once. The router keeps a table that maps each internal (IP, port) pair to a different public port. This technique is:","options":["Static NAT","DHCP relay","Proxy ARP","PAT (NAT overload)"],"answer":3,"explanation":"Port Address Translation (NAT overload) shares one public IP by giving every inside connection its own source port. Static NAT maps one private address to one public address and could not serve 300 hosts with one IP.","difficulty":"moderate","source":"IBM · Deloitte pattern"},
  {"id":"cs-computer-networks-17","question":"Which IPv4 header field stops a packet from circulating forever if a routing loop forms?","options":["Time to Live (TTL)","Fragment offset","Identification","Header checksum"],"answer":0,"explanation":"Every router decrements TTL by 1 and drops the packet when it reaches 0, sending back ICMP Time Exceeded. IPv6 calls the same field Hop Limit.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-18","question":"How many parity (check) bits does a single-error-correcting Hamming code need for 11 data bits?","options":["3","4","5","11"],"answer":1,"explanation":"Need the smallest r with 2^r ≥ m + r + 1. For m = 11: r = 3 gives 8 < 15, r = 4 gives 16 ≥ 16, so r = 4 (the (15, 11) code).","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id": "cs-computer-networks-19", "question": "A Go-Back-N protocol uses 3-bit sequence numbers. What is the largest sender window that still works correctly?", "options": ["8", "4", "7", "3"], "answer": 2, "explanation": "With k-bit sequence numbers Go-Back-N allows a window of at most 2^k − 1 = 7. A window of 8 would let the receiver mistake a retransmitted old frame 0 for a new frame 0. (Selective Repeat would be limited to 2^(k−1) = 4.)", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-20","question":"Under classful addressing, 150.20.3.4 belongs to which class, and what is its default subnet mask?","options":["Class A, 255.0.0.0","Class B, 255.255.255.0","Class C, 255.255.255.0","Class B, 255.255.0.0"],"answer":3,"explanation":"First octet 128–191 means class B (150 lies in this range), whose default mask is 255.255.0.0 (/16). Class A is 1–126 and class C is 192–223.","difficulty":"easy","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-21","question":"A host has the address 172.16.45.200/20. What is the network address of its subnet?","options":["172.16.32.0","172.16.40.0","172.16.45.0","172.16.48.0"],"answer":0,"explanation":"A /20 mask is 255.255.240.0, so the third octet moves in blocks of 16. 45 lies in 32–47, so the network is 172.16.32.0 (broadcast 172.16.47.255). 172.16.45.0 is what you get by wrongly assuming /24.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-22","question":"What is the directed broadcast address of the subnet containing 10.37.190.77/19?","options":["10.37.190.255","10.37.191.255","10.37.159.255","10.37.255.255"],"answer":1,"explanation":"A /19 mask is 255.255.224.0, so the third octet steps by 32: 160–191. The subnet is 10.37.160.0 and its broadcast is 10.37.191.255.","difficulty":"moderate","source":"Product-company MCQ pattern"},
  {"id": "cs-computer-networks-23", "question": "The block 10.0.0.0/8 must be divided into at least 500 equal subnets, each with as many hosts as possible. How many usable hosts will each subnet have?", "options": ["65,534", "16,382", "32,766", "32,768"], "answer": 2, "explanation": "500 subnets need 9 borrowed bits (2⁹ = 512 ≥ 500; 2⁸ = 256 is too few), giving /17. Host bits = 32 − 17 = 15, so 2¹⁵ − 2 = 32,766 usable hosts. 32,768 forgets to remove network and broadcast.", "difficulty": "hard", "source": "Cognizant · Capgemini pattern"},
  {"id":"cs-computer-networks-24","question":"Which address is in the same subnet as 192.168.5.130/27 and can be assigned to a host?","options":["192.168.5.127","192.168.5.159","192.168.5.160","192.168.5.158"],"answer":3,"explanation":"/27 → blocks of 32 in the last octet, so .130 lies in 128–159. .158 is a usable host; .159 is the broadcast of that subnet, .127 belongs to the previous subnet and .160 to the next.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-25","question":"An ISP wants to advertise the four networks 200.10.4.0/24, 200.10.5.0/24, 200.10.6.0/24 and 200.10.7.0/24 as one route. What is the aggregate?","options":["200.10.4.0/22","200.10.0.0/21","200.10.4.0/23","200.10.4.0/24"],"answer":0,"explanation":"Third octets 4–7 are 000001|00 to 000001|11, so the first 22 bits match and the four /24s fill exactly one /22 starting at 4 (4 is a multiple of 4). A /23 covers only two of them; a /21 would also cover 0–3, which this ISP does not own.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-computer-networks-26","question":"Data bits 10011010 are sent using CRC with generator polynomial x³ + x² + 1. What bit string is actually transmitted?","options":["10011010011","10011010101","1001101101","10011010110"],"answer":1,"explanation":"The generator is 1101, so append 3 zeros (10011010000) and divide modulo 2; the remainder is 101. The transmitted frame is the data followed by the remainder: 10011010101.","difficulty":"hard","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-computer-networks-27","question":"Using the (7, 4) Hamming code with even parity and bit layout p1 p2 d3 p4 d5 d6 d7 (data in positions 3, 5, 6, 7), what codeword is sent for the data 1011?","options":["1010101","0111011","0110011","1011010"],"answer":2,"explanation":"d3 = 1, d5 = 0, d6 = 1, d7 = 1. p1 covers 3, 5, 7: 1⊕0⊕1 = 0. p2 covers 3, 6, 7: 1⊕1⊕1 = 1. p4 covers 5, 6, 7: 0⊕1⊕1 = 0. Codeword p1 p2 d3 p4 d5 d6 d7 = 0 1 1 0 0 1 1.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id": "cs-computer-networks-28", "question": "A stop-and-wait link runs at 1 Mbps with 1000-bit frames and a one-way propagation delay of 20 ms. Ignoring ACK size and processing, what is the link utilisation?", "options": ["About 4.8%", "About 50%", "About 1.2%", "About 2.4%"], "answer": 3, "explanation": "Transmission time Tt = 1000/10⁶ = 1 ms, so a = Tp/Tt = 20. Efficiency = 1/(1 + 2a) = 1/41 ≈ 0.0244, i.e. about 2.4%. Using 1/(1 + a) gives 4.8%, the usual slip of forgetting the ACK's return trip.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-29", "question": "A Selective Repeat protocol uses 4-bit sequence numbers. What is the maximum window size (equal sender and receiver windows)?", "options": ["15", "16", "7", "8"], "answer": 3, "explanation": "For Selective Repeat the window must not exceed half the sequence space: 2^(4−1) = 8. 15 is the Go-Back-N limit (2⁴ − 1), the most common mix-up.", "difficulty": "moderate", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-30","question":"A CSMA/CD network runs at 10 Mbps over a 2 km cable where signals travel at 2 × 10⁸ m/s. What is the minimum frame size needed for collision detection to work?","options":["25 bytes","12.5 bytes","50 bytes","200 bytes"],"answer":0,"explanation":"One-way propagation delay Tp = 2000/(2 × 10⁸) = 10 μs. The frame must still be transmitting after a round trip: Lmin = 2·Tp·B = 2 × 10⁻⁵ × 10⁷ = 200 bits = 25 bytes. 200 bytes confuses bits with bytes; 12.5 bytes uses only one-way delay.","difficulty":"hard","source":"Cognizant · Capgemini pattern"},
  {"id": "cs-computer-networks-31", "question": "A 4000-byte IPv4 datagram (20-byte header, no options) must cross a link with MTU 1500 bytes. What is the fragment offset field value of the last fragment?", "options": ["2960", "370", "1480", "185"], "answer": 1, "explanation": "Each fragment can carry 1480 data bytes (a multiple of 8). 3980 data bytes split as 1480 + 1480 + 1020, so the last fragment starts at byte 2960, and the offset field counts 8-byte units: 2960/8 = 370. 185 is the second fragment's offset; 2960 forgets to divide by 8.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-32","question":"A TCP connection has a 65,535-byte receive window (no window scaling) and a round-trip time of 50 ms. What is the best throughput it can reach, however fast the link is?","options":["About 1.3 Mbps","About 21 Mbps","About 10.5 Mbps","About 655 Mbps"],"answer":2,"explanation":"At most one window can be in flight per RTT: 65,535 × 8 bits / 0.05 s ≈ 10,485,600 bps ≈ 10.5 Mbps. 1.3 Mbps leaves the answer in bytes per second (MBps), and 21 Mbps uses one-way delay instead of RTT.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-computer-networks-33","question":"A client's SYN carries initial sequence number 1000. After the handshake it sends one segment with 200 bytes of data. What sequence number does that segment carry, and what acknowledgement number does the server send back for it?","options":["Sequence 1000, ACK 1200","Sequence 1001, ACK 1200","Sequence 1000, ACK 1201","Sequence 1001, ACK 1201"],"answer":3,"explanation":"The SYN consumes one sequence number, so the first data byte is 1001. The segment covers bytes 1001–1200, and TCP acknowledges the next byte it expects: 1201.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-34","question":"Host A (192.168.1.10/24) sends a packet to 8.8.8.8 through its default gateway 192.168.1.1. Whose MAC address does A's ARP request ask for?","options":["The default gateway 192.168.1.1","8.8.8.8","The DNS server","The broadcast MAC FF:FF:FF:FF:FF:FF"],"answer":0,"explanation":"The destination is off-subnet, so the frame is addressed at layer 2 to the next hop, the gateway, while the IP header still says 8.8.8.8. A never ARPs for a remote IP; FF:FF:FF:FF:FF:FF is only the destination of the ARP request frame itself.","difficulty":"moderate","source":"Wipro · Accenture pattern"},
  {"id":"cs-computer-networks-35","question":"How does traceroute learn the address of each router along the path?","options":["It reads the Record Route option that every router fills in","It sends probes with TTL = 1, 2, 3, … and records the ICMP Time Exceeded reply from each router","It sends one ICMP Echo Request and every router replies with an ICMP Echo Reply","It asks each router through SNMP for its next hop"],"answer":1,"explanation":"Each probe's TTL expires one hop further away; the router that drops it returns ICMP Time Exceeded, revealing its address. The final host answers with Echo Reply (Windows) or Port Unreachable (UDP-based Unix traceroute).","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-36","question":"A router's table holds 10.0.0.0/8 → interface A, 10.1.0.0/16 → interface B, 10.1.128.0/17 → interface C and a default route → interface D. On which interface is a packet for 10.1.130.5 sent?","options":["B","A","C","D"],"answer":2,"explanation":"All three prefixes match 10.1.130.5 (130 ≥ 128 falls in 10.1.128.0/17), and the router uses longest-prefix match, so the /17 entry wins. A packet for 10.1.100.5 would have gone to B.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-computer-networks-37","question":"A token bucket has capacity 1 MB and fills at 2 MB/s; the output line can run at 10 MB/s. Starting with a full bucket, for how long can the host send at the full 10 MB/s?","options":["0.1 s","0.5 s","0.083 s","0.125 s"],"answer":3,"explanation":"Burst length S satisfies C + ρS = MS, so S = C/(M − ρ) = 1/(10 − 2) = 0.125 s. 0.1 s (= C/M) ignores the tokens that keep arriving during the burst.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id":"cs-computer-networks-38","question":"A 3000 Hz telephone channel has a signal-to-noise ratio of 30 dB. What is its Shannon capacity, approximately?","options":["About 30 kbps","About 90 kbps","About 6 kbps","About 15 kbps"],"answer":0,"explanation":"30 dB means SNR = 10^(30/10) = 1000. C = B·log₂(1 + SNR) = 3000 × log₂(1001) ≈ 3000 × 9.97 ≈ 29.9 kbps. Plugging 30 directly gives 3000 × log₂31 ≈ 14.9 kbps, the classic dB trap.","difficulty":"moderate","source":"Cognizant · Capgemini pattern"},
  {"id": "cs-computer-networks-39", "question": "Which side of a TCP connection goes through the TIME_WAIT state, and for how long?", "options": ["The side that closes last (passive close), for 2 × MSL", "Both sides, for one RTT", "The side that closes first (active close), for 2 × MSL", "The server only, for 1 × MSL"], "answer": 2, "explanation": "The active closer sends the final ACK and waits 2·MSL so that a lost final ACK can be resent and stale duplicate segments die out before the same port pair is reused.", "difficulty": "moderate", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-40","question":"A web page consists of a base HTML file and 10 small images on the same server. Using persistent HTTP without pipelining and ignoring transmission times, how many RTTs does it take to fetch everything?","options":["22 RTTs","12 RTTs","3 RTTs","11 RTTs"],"answer":1,"explanation":"One RTT for the TCP handshake and one for the base file = 2 RTT; then each image needs one request-response RTT on the same connection = 10. Total 12. Non-persistent HTTP would need 2 per object = 22; pipelining would need 2 + 1 = 3.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-computer-networks-41", "question": "A user's laptop resolves www.example.org using a local DNS server that has nothing cached. Which description of the lookup is the usual one?", "options": ["The laptop itself contacts the root, TLD and authoritative servers in turn", "The root server forwards the query to the TLD server, which forwards it to the authoritative server", "The laptop sends a recursive query to the local server, which then queries the root, the .org TLD and the authoritative server iteratively", "The local server broadcasts the query on the LAN until the authoritative server answers"], "answer": 2, "explanation": "Stub resolvers ask the local resolver recursively; the local resolver walks the hierarchy with iterative queries, getting a referral from the root and the TLD before the authoritative server answers. Root servers do not perform recursion.", "difficulty": "moderate", "source": "IBM · Deloitte pattern"},
  {"id":"cs-computer-networks-42","question":"A noiseless channel of bandwidth 4 kHz carries a signal with 8 distinct levels. What is the maximum bit rate according to Nyquist?","options":["8 kbps","12 kbps","32 kbps","24 kbps"],"answer":3,"explanation":"Nyquist: C = 2B·log₂L = 2 × 4000 × log₂8 = 8000 × 3 = 24,000 bps. 32 kbps multiplies by 8 levels instead of log₂8 = 3 bits.","difficulty":"moderate","source":"HCL · Tech Mahindra pattern"},
  {"id": "cs-computer-networks-43", "question": "How many of the following statements about TCP and UDP are correct?\n1. UDP header is 8 bytes; the minimum TCP header is 20 bytes.\n2. TCP preserves message boundaries, so two send() calls of 100 bytes are always read as two 100-byte reads.\n3. Both TCP and UDP carry a checksum that covers a pseudo-header containing the IP addresses.\n4. UDP can be used for multicast, but TCP cannot.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1 is true (8 vs 20–60 bytes). 2 is false: TCP is a byte stream and may merge or split the data; UDP is the one that preserves datagram boundaries. 3 is true (the UDP checksum is optional in IPv4 but still uses the pseudo-header). 4 is true, since TCP is strictly one-to-one. So three are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-44", "question": "Using VLSM, the block 192.168.1.0/24 is split for three LANs needing 100, 50 and 20 hosts, assigning the largest LAN first from the lowest addresses. What is the subnet given to the 20-host LAN?", "options": ["192.168.1.192/27", "192.168.1.160/27", "192.168.1.128/27", "192.168.1.192/26"], "answer": 0, "explanation": "100 hosts need 7 host bits → 192.168.1.0/25 (0–127). 50 hosts need 6 → 192.168.1.128/26 (128–191). 20 hosts need 5 (30 usable) → next free block 192.168.1.192/27. .128/27 and .160/27 overlap the 50-host subnet; a /26 would waste 32 addresses.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-45", "question": "An organisation owns 200.10.5.0/24, 200.10.6.0/24, 200.10.7.0/24 and 200.10.8.0/24. What is the smallest single CIDR block that covers all four?", "options": ["200.10.4.0/22", "200.10.0.0/20", "200.10.5.0/22", "200.10.0.0/21"], "answer": 1, "explanation": "Third octets: 5 = 00000101, 8 = 00001000. They agree only in the first 4 bits (0000), so the prefix is 16 + 4 = 20 bits: 200.10.0.0/20 (third octet 0–15). 200.10.4.0/22 covers only 4–7, 200.10.5.0/22 is not a valid block boundary, and a /21 covers 0–7 and misses 8.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-46","question":"A sender uses CRC generator 1011 and transmits the data 1101101 followed by its CRC. In transit the third bit from the left is flipped. What remainder does the receiver get when it divides the received 10 bits by 1011, and what does it conclude?","options":["111; error detected","000; frame accepted","001; error detected","010; error detected"],"answer":2,"explanation":"The CRC of 1101101 with 1011 is 111, so 1101101111 is sent and leaves remainder 000. With bit 3 flipped the receiver gets 1111101111; dividing by 1011 leaves 001, which is non-zero, so the error is detected (any single-bit error is caught because the generator has more than one term).","difficulty":"hard","source":"HCL · Tech Mahindra pattern"},
  {"id": "cs-computer-networks-47", "question": "A (7, 4) even-parity Hamming codeword (layout p1 p2 d3 p4 d5 d6 d7) is received as 0110111. Assuming at most one bit is in error, what are the four data bits d3 d5 d6 d7 after correction?", "options": ["1111", "1010", "0111", "1011"], "answer": 3, "explanation": "Check p1 (1,3,5,7): 0⊕1⊕1⊕1 = 1. p2 (2,3,6,7): 1⊕1⊕1⊕1 = 0. p4 (4,5,6,7): 0⊕1⊕1⊕1 = 1. Syndrome = 4 + 1 = 5, so bit 5 is wrong: corrected word 0110011, data 1, 0, 1, 1 = 1011. 1111 is the uncorrected data.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-48","question":"A link has transmission time 1 ms per frame and one-way propagation delay 24.5 ms. Using Selective Repeat with sender window equal to receiver window, what is the minimum number of sequence-number bits needed to keep the link fully busy?","options":["7","5","8","6"],"answer":0,"explanation":"Full utilisation needs window ≥ 1 + 2a = 1 + 2(24.5) = 50 frames. Selective Repeat requires window ≤ 2^(k−1), so 2^(k−1) ≥ 50 → k − 1 = 6 → k = 7. Go-Back-N would need only 2^k − 1 ≥ 50 → k = 6, the trap answer.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id":"cs-computer-networks-49","question":"TCP Tahoe starts with cwnd = 1 MSS and ssthresh = 16 MSS. cwnd doubles each RTT in slow start (but is capped at ssthresh when doubling would overshoot it) and grows by 1 MSS per RTT in congestion avoidance. A timeout happens during RTT 9. What is cwnd during RTT 15?","options":["16 MSS","11 MSS","17 MSS","10 MSS"],"answer":1,"explanation":"RTT 1–5: 1, 2, 4, 8, 16; RTT 6–9: 17, 18, 19, 20. Timeout at cwnd 20 → ssthresh = 10, cwnd = 1. RTT 10–14: 1, 2, 4, 8, 10 (capped); RTT 15: 11. 16 comes from keeping the old ssthresh, 10 from stopping one RTT early.","difficulty":"very-hard","source":"Product-company MCQ pattern"},
  {"id": "cs-computer-networks-50", "question": "How many of the following statements about TCP congestion control (Reno) are correct?\n1. On three duplicate ACKs, ssthresh is set to half the current cwnd and the lost segment is retransmitted without waiting for a timeout.\n2. On a retransmission timeout, cwnd drops to 1 MSS and slow start begins again.\n3. In slow start, cwnd grows linearly by one MSS per RTT.\n4. The receiver's advertised window, not cwnd, is the only limit on how much unacknowledged data a sender may have.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "1 (fast retransmit / fast recovery) and 2 are correct. 3 is wrong: slow start grows exponentially (doubling per RTT); linear growth is congestion avoidance. 4 is wrong: the sender is limited by min(cwnd, rwnd). So two are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-51","question":"TCP sequence numbers are 32 bits and count bytes. On a 1 Gbps link sending continuously, roughly how long does it take for the sequence numbers to wrap around?","options":["About 4.3 seconds","About 4.3 minutes","About 34 seconds","About 0.5 seconds"],"answer":2,"explanation":"2³² bytes = 4,294,967,296 bytes = 34,359,738,368 bits; at 10⁹ bits/s that is about 34.4 s. 4.3 s comes from treating the sequence space as bits instead of bytes — which is why fast links need the PAWS timestamp option.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-computer-networks-52","question":"Under distance-vector routing, router A has direct links to B (cost 2) and C (cost 5). B advertises distances {D: 7, E: 1} and C advertises {D: 3, E: 4}. What does A's new table give for D and E?","options":["D = 9 via B, E = 3 via B","D = 8 via C, E = 9 via C","D = 3 via C, E = 1 via B","D = 8 via C, E = 3 via B"],"answer":3,"explanation":"Bellman–Ford: D = min(2 + 7, 5 + 3) = min(9, 8) = 8 via C; E = min(2 + 1, 5 + 4) = min(3, 9) = 3 via B. Copying the neighbour's advertised value without adding the link cost gives the third option.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id": "cs-computer-networks-53", "question": "An undirected network has links A–B 4, A–C 1, B–C 2, B–D 5, C–D 8, C–E 10, D–E 2, D–F 6, E–F 3. What is the cost of the shortest path from A to F found by Dijkstra's algorithm?", "options": ["14", "15", "13", "12"], "answer": 2, "explanation": "Dijkstra from A: C = 1, B = min(4, 1 + 2) = 3, D = min(3 + 5, 1 + 8) = 8, E = min(1 + 10, 8 + 2) = 10, F = min(8 + 6, 10 + 3) = 13 along A–C–B–D–E–F. 14 is A–B–D–E–F (missing the cheaper route to B through C) and 15 is A–C–D–F.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-54","question":"Match each protocol with its default port.\nP. SSH   Q. SMTP   R. SNMP   S. DNS\n1. 25   2. 22   3. 53   4. 161","options":["P-2, Q-1, R-4, S-3","P-2, Q-1, R-3, S-4","P-1, Q-2, R-4, S-3","P-2, Q-4, R-1, S-3"],"answer":0,"explanation":"SSH = 22, SMTP = 25, DNS = 53, SNMP = 161 (agents; traps go to 162). Mixing 22/25 and 53/161 are the usual slips.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-55","question":"A hub with 3 PCs is plugged into one port of switch S1. S1 also connects 4 PCs directly and one port to router R. R's other interface goes to switch S2, which connects 5 PCs. How many collision domains and broadcast domains are there? (Each switch port is its own collision domain.)","options":["8 collision domains, 2 broadcast domains","12 collision domains, 2 broadcast domains","12 collision domains, 1 broadcast domain","14 collision domains, 2 broadcast domains"],"answer":1,"explanation":"S1 has 6 used ports (hub segment, 4 PCs, router link) = 6 collision domains, the hub and its 3 PCs being one. S2 has 6 (router link + 5 PCs). Total 12. Only the router splits broadcast domains, so there are 2. Counting each hub PC separately gives 14.","difficulty":"hard","source":"Cognizant · Capgemini pattern"},
  {"id": "cs-computer-networks-56", "question": "Assertion (A): An ARP request is sent as a layer-2 broadcast, but the ARP reply is normally unicast.\nReason (R): The requester does not yet know the target's MAC address, whereas the replier learns the requester's MAC from the request itself.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 0, "explanation": "The request must reach every host because the target MAC is unknown (hence FF:FF:FF:FF:FF:FF). The request carries the sender's IP and MAC, so the target can reply straight to it with a unicast frame. R explains exactly why the two differ.", "difficulty": "hard", "source": "Wipro · Accenture pattern"},
  {"id": "cs-computer-networks-57", "question": "Assertion (A): DNS uses only UDP, because each query and answer fits in a single datagram.\nReason (R): UDP avoids the connection set-up delay of TCP.", "options": ["Both A and R are true and R is the correct explanation of A", "Both A and R are true but R is not the correct explanation of A", "A is true but R is false", "A is false but R is true"], "answer": 3, "explanation": "R is true, which is why ordinary lookups prefer UDP. A is false: DNS falls back to TCP port 53 when a response is truncated (too large for UDP) and always uses TCP for zone transfers, and DNS-over-TLS also runs on TCP.", "difficulty": "hard", "source": "IBM · Deloitte pattern"},
  {"id": "cs-computer-networks-58", "question": "How many of the following statements about DHCP are correct?\n1. The DHCPDISCOVER message is broadcast with source IP 0.0.0.0.\n2. DHCP servers listen on UDP port 67 and clients on UDP port 68.\n3. When the DHCP server is on a different subnet, a relay agent (for example ip helper-address on the router) is needed.\n4. A server can always give a particular client the same address through a reservation tied to its MAC address.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are correct. Addresses are normally leased (renewal tried at T1 = 50% and rebinding at T2 = 87.5% of the lease), but a reservation (static binding) on the server hands the same address to a given MAC every time.", "difficulty": "hard", "source": "Cognizant · Capgemini pattern"},
  {"id": "cs-computer-networks-59", "question": "How many of the following statements about NAT are correct?\n1. NAT breaks the end-to-end principle because outside hosts cannot start connections to inside hosts without port forwarding.\n2. IPsec AH works through NAT unchanged because AH does not protect the IP header.\n3. NAT must recompute the IP header checksum and also the TCP/UDP checksum when it rewrites addresses.\n4. NAT also rewrites the MAC addresses of inside hosts so that they stay hidden on the Internet.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "1 and 3 are correct (the TCP/UDP checksum covers a pseudo-header containing the IP addresses, so it must be fixed). 2 is wrong: AH authenticates the immutable IP header fields including the addresses, so NAT's rewrite makes the AH check fail. 4 is wrong: MAC addresses never leave the local link anyway; each router rewrites the layer-2 header hop by hop, NAT or not. So two are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id":"cs-computer-networks-60","question":"A 5000-byte IPv4 datagram (20-byte header) must cross a link with MTU 1420 bytes. What are the fragment offset and total length of the last fragment?","options":["Offset 4200, total length 800 bytes","Offset 525, total length 780 bytes","Offset 525, total length 800 bytes","Offset 350, total length 1420 bytes"],"answer":2,"explanation":"Data per fragment = 1400 bytes (1420 − 20, already a multiple of 8). 4980 data bytes → 1400 + 1400 + 1400 + 780, i.e. 4 fragments. The last starts at byte 4200 → offset 4200/8 = 525, and its total length is 780 + 20 = 800. 780 forgets the header; 4200 forgets the 8-byte unit.","difficulty":"hard","source":"Product-company MCQ pattern"},
  {"id":"cs-computer-networks-61","question":"A code has exactly four codewords: 00000, 01011, 10101 and 11110. Which statement about its error handling is correct?","options":["It can detect up to 4-bit errors and correct 2-bit errors","It can detect up to 3-bit errors and correct 2-bit errors","It can detect 1-bit errors but correct none","It can detect up to 2-bit errors and correct 1-bit errors"],"answer":3,"explanation":"Pairwise distances are 3, 3, 4, 4, 3, 3, so d_min = 3 (take the minimum, not the largest 4). Detect d_min − 1 = 2 errors; correct ⌊(d_min − 1)/2⌋ = 1 error.","difficulty":"hard","source":"HCL · Tech Mahindra pattern"},
  {"id":"cs-computer-networks-62","question":"In slotted ALOHA, the offered load is G = 2 frames per slot. What fraction of slots carry a successful frame?","options":["About 0.27","About 0.37","About 0.14","About 0.04"],"answer":0,"explanation":"Slotted ALOHA: S = G·e^(−G) = 2 × e^(−2) ≈ 2 × 0.135 ≈ 0.271. 0.37 is the peak, reached only at G = 1; 0.14 drops the factor G (e^(−2) alone); 0.04 wrongly uses the pure-ALOHA formula 2·e^(−4).","difficulty":"hard","source":"Wipro · Accenture pattern"},
  {"id": "cs-computer-networks-63", "question": "For the host 131.45.214.9/22, how many usable host addresses does its subnet have, and what is the last usable host address?", "options": ["1022 hosts; last host 131.45.214.254", "1022 hosts; last host 131.45.215.254", "1024 hosts; last host 131.45.215.255", "510 hosts; last host 131.45.215.254"], "answer": 1, "explanation": "/22 → third octet in blocks of 4: 212–215. Network 131.45.212.0, broadcast 131.45.215.255. Host bits = 10 → 2¹⁰ − 2 = 1022 usable, and the last usable is one below the broadcast: 131.45.215.254.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id":"cs-computer-networks-64","question":"Which one of these is NOT a function of the transport layer?","options":["Splitting application data into segments and reassembling them","Delivering data to the right process using port numbers","Choosing the route a packet takes across routers","End-to-end flow control between the two hosts"],"answer":2,"explanation":"Segmentation, process-to-process delivery (ports) and end-to-end flow/error control belong to the transport layer. Path selection across routers is a network-layer job.","difficulty":"moderate","source":"TCS NQT · Infosys pattern"},
  {"id": "cs-computer-networks-65", "question": "How many of the following statements about IPv6 are correct?\n1. The base IPv6 header has a fixed size of 40 bytes.\n2. IPv6 has no broadcast; multicast and anycast replace it.\n3. Routers fragment IPv6 packets when they exceed the next link's MTU.\n4. The IPv6 header drops the header checksum that IPv4 has.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1, 2 and 4 are correct. 3 is wrong: in IPv6 only the source host fragments (using the Fragment extension header after Path MTU discovery); routers drop oversized packets and send ICMPv6 Packet Too Big. So three are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-66", "question": "How many of the following statements about HTTPS (TLS) are correct?\n1. The server's certificate lets the client verify the server's identity through a chain of trusted CAs.\n2. Bulk application data is encrypted with a symmetric session key agreed during the handshake.\n3. HTTPS hides the destination IP address of the server from on-path observers.\n4. In TLS 1.3 the server's certificate travels in plaintext so that middleboxes can inspect it.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 1, "explanation": "1 and 2 are correct. 3 is wrong: the IP header is outside TLS, so the server's address (and usually the hostname via SNI) is still visible. 4 is wrong: TLS 1.3 encrypts everything after ServerHello, including the certificate, using handshake keys. So two are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-67", "question": "A 100 Mbps path has a one-way propagation delay of 25 ms. To keep it full, a TCP sender needs a window equal to the bandwidth-delay product of one RTT. What is the smallest TCP window-scale shift count that allows this window?", "options": ["3", "5", "9", "4"], "answer": 3, "explanation": "BDP = 100 × 10⁶ × 0.05 s = 5 × 10⁶ bits = 625,000 bytes. The 16-bit window field holds at most 65,535; 65,535 × 2³ = 524,280 is too small, while 65,535 × 2⁴ = 1,048,560 suffices, so shift = 4. Using one-way delay (312,500 bytes) would wrongly suggest 3.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-68", "question": "How many of the following OSI layer descriptions are correct?\n1. The session layer manages dialogue control and synchronisation checkpoints.\n2. The presentation layer handles translation, encryption and compression.\n3. The transport layer provides end-to-end (process-to-process) delivery.\n4. The data link layer provides node-to-node delivery and detects errors using a trailer such as the FCS.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 3, "explanation": "All four are standard OSI descriptions. The tempting doubt is 4, but framing, MAC addressing and error detection with a frame check sequence (CRC trailer) are exactly the data link layer's node-to-node job; ports belong to the transport layer.", "difficulty": "hard", "source": "TCS NQT · Infosys pattern"},
  {"id": "cs-computer-networks-69", "question": "Which of these addresses (written with its prefix length) can be assigned to a host interface?", "options": ["172.17.0.0/15", "10.10.15.255/20", "10.10.16.0/20", "192.168.1.255/23"], "answer": 0, "explanation": "172.16.0.0/15 spans 172.16.0.0–172.17.255.255, so 172.17.0.0 is an ordinary host address in the middle of the block despite ending in .0. 10.10.15.255/20 and 192.168.1.255/23 are broadcast addresses, and 10.10.16.0/20 is a network address.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-70", "question": "Go-Back-N with window size 3 sends frames 1 to 7. The first transmission of frame 3 is lost; nothing else is lost. The sender fills its window before frame 3's timer expires. How many frame transmissions take place in total?", "options": ["8", "10", "9", "11"], "answer": 1, "explanation": "Frames 1, 2, 3(lost) go out; ACKs for 1 and 2 slide the window so 4 and 5 are sent (5 so far) but the receiver discards them. Frame 3 times out, so 3, 4, 5 are resent (8), then 6 and 7 (10). Selective Repeat would need only 8.", "difficulty": "very-hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-71", "question": "What is the 16-bit Internet checksum (ones'-complement of the ones'-complement sum) of the words 0xF0F0 and 0x1F1F?", "options": ["0x100F", "0x1010", "0xEFEF", "0xEFF0"], "answer": 2, "explanation": "0xF0F0 + 0x1F1F = 0x1100F. Fold the carry: 0x100F + 0x1 = 0x1010. Complement: 0xEFEF. Skipping the carry wrap-around gives ~0x100F = 0xEFF0.", "difficulty": "hard", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-computer-networks-72","question":"Which set contains ONLY protocols that normally run over UDP?","options":["HTTP/2, TFTP, SNMP","FTP, SNMP, DHCP","TFTP, SMTP, DNS zone transfer","TFTP, SNMP, DHCP"],"answer":3,"explanation":"TFTP (69), SNMP (161/162) and DHCP (67/68) use UDP. FTP, SMTP, DNS zone transfers and HTTP/2 run over TCP (HTTP/3 is the one on QUIC/UDP).","difficulty":"moderate","source":"Wipro · Accenture pattern"},
  {"id": "cs-computer-networks-73", "question": "How many of the following statements about routing protocols are correct?\n1. RIP uses hop count and treats 16 hops as unreachable.\n2. OSPF is a link-state protocol in which every router runs Dijkstra on its link-state database.\n3. Split horizon with poison reverse completely removes count-to-infinity in every topology.\n4. BGP is a path-vector protocol used between autonomous systems.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1, 2 and 4 are correct. 3 is wrong: split horizon and poison reverse fix two-node loops, but loops of three or more routers can still count to infinity. So three are correct.", "difficulty": "hard", "source": "Product-company MCQ pattern"},
  {"id": "cs-computer-networks-74", "question": "How many of the following statements about the CRC generator x³ + x + 1 (1011) are correct?\n1. It detects every single-bit error.\n2. It detects every burst error of length 3 or less.\n3. It detects every error that flips an odd number of bits.\n4. The CRC it produces is 3 bits long.", "options": ["Only one", "Only two", "Only three", "All four"], "answer": 2, "explanation": "1, 2 and 4 are correct (degree 3 → 3-bit CRC, catches all bursts ≤ 3). 3 is false: a generator detects all odd-weight errors only if it has (x + 1) as a factor, i.e. if it evaluates to 0 at x = 1; here 1 + 1 + 1 = 1 (mod 2), so (x + 1) is not a factor. So three are correct.", "difficulty": "hard", "source": "HCL · Tech Mahindra pattern"},
  {"id":"cs-computer-networks-75","question":"A router forwards an IPv4 packet with no fragmentation, no NAT and no options. Which fields of the IP header does it change?","options":["TTL and header checksum only","TTL, header checksum and identification","TTL, header checksum and source IP address","TTL only"],"answer":0,"explanation":"The router decrements TTL, and because the header changed it must recompute the header checksum. Identification and addresses are untouched (addresses change only with NAT); the MAC addresses do change, but they are in the frame header, not the IP header.","difficulty":"hard","source":"IBM · Deloitte pattern"},
  {"id":"cs-computer-networks-76","question":"Which OSI layer is responsible for data format translation, encryption and compression, so that the receiving application can understand the data?","options":["Session layer","Presentation layer","Application layer","Transport layer"],"answer":1,"explanation":"The presentation layer handles syntax and representation: character encoding, encryption and compression. The session layer manages dialogues (sessions); the application layer provides network services to the user program.","difficulty":"easy","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-computer-networks-77","question":"An email client sends an outgoing message to its mail server. Which protocol does it normally use for this step?","options":["POP3","IMAP","SMTP","SNMP"],"answer":2,"explanation":"SMTP is used to send (push) mail, both client-to-server and server-to-server. POP3 and IMAP are used to retrieve mail from a mailbox; SNMP is for network management.","difficulty":"easy","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-computer-networks-78","question":"A network 10.5.6.0/26 is to be split into equal subnets of size /29. How many such subnets can be made?","options":["6","3","16","8"],"answer":3,"explanation":"Going from /26 to /29 borrows 3 bits, giving 2³ = 8 subnets (each with 8 addresses, 6 usable). 6 confuses the subnet count with the usable hosts per /29.","difficulty":"moderate","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-computer-networks-79","question":"What are the minimum header sizes of a UDP datagram and a TCP segment?","options":["UDP 8 bytes, TCP 20 bytes","UDP 20 bytes, TCP 20 bytes","UDP 8 bytes, TCP 60 bytes","UDP 4 bytes, TCP 20 bytes"],"answer":0,"explanation":"UDP has a fixed 8-byte header (ports, length, checksum). TCP needs at least 20 bytes and up to 60 bytes with options. 60 bytes is TCP’s maximum, not minimum.","difficulty":"easy","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-computer-networks-80","question":"What is the network address of the subnet that contains the host 192.168.10.77/27?","options":["192.168.10.72","192.168.10.64","192.168.10.0","192.168.10.96"],"answer":1,"explanation":"A /27 has blocks of 32 in the last octet: 0, 32, 64, 96, … 77 falls in 64–95, so the network is 192.168.10.64 (broadcast .95). .96 is the next subnet.","difficulty":"moderate","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-computer-networks-81","question":"Which DNS record type maps a host name to an IPv6 address?","options":["A","CNAME","AAAA","PTR"],"answer":2,"explanation":"AAAA (“quad-A”) records hold 128-bit IPv6 addresses; A records hold IPv4 addresses. CNAME is an alias to another name, and PTR maps an address back to a name.","difficulty":"easy","source":"Product-company interview pattern"},
  {"id":"cs-computer-networks-82","question":"A switch receives a frame whose destination MAC address is not yet in its MAC address table. What does the switch do?","options":["Drops the frame and sends an ICMP error","Sends an ARP request for the destination MAC","Sends the frame back out of the incoming port","Floods the frame out of every port except the one it arrived on"],"answer":3,"explanation":"An unknown unicast is flooded to all other ports in the VLAN; when the destination replies, the switch learns its port. Switches do not send ICMP or ARP for frames they forward — those are layer-3 mechanisms.","difficulty":"easy","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-computer-networks-83","question":"A video-calling app sends small voice packets every 20 ms. Why do such apps usually prefer UDP over TCP for the media stream?","options":["A late packet is useless, and TCP’s retransmission with in-order delivery would hold back newer packets behind a lost one","UDP encrypts packets, while TCP does not","TCP cannot carry packets smaller than 1 KB","UDP guarantees delivery faster than TCP"],"answer":0,"explanation":"For real-time audio, a retransmitted packet arrives too late to be played, and TCP would also block all later data until the gap is filled (head-of-line blocking). UDP lets the app skip losses. UDP guarantees nothing, and neither protocol encrypts by itself.","difficulty":"moderate","source":"Product-company interview pattern"},
  {"id":"cs-computer-networks-84","question":"What is the broadcast address of the subnet containing 10.20.30.40/13?","options":["10.20.255.255","10.23.255.255","10.31.255.255","10.16.255.255"],"answer":1,"explanation":"A /13 mask is 255.248.0.0, so the second octet moves in blocks of 8: 16–23 contains 20. Network 10.16.0.0, broadcast 10.23.255.255. 10.20.255.255 treats it like a /16.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-computer-networks-85","question":"Which address is in the same subnet as 172.16.8.1/21?","options":["172.16.16.1","172.16.7.255","172.16.15.254","172.17.8.1"],"answer":2,"explanation":"A /21 mask is 255.255.248.0: the third octet moves in blocks of 8, so 172.16.8.0/21 spans 172.16.8.0 to 172.16.15.255. Only 172.16.15.254 falls inside. 172.16.7.255 is the broadcast of the previous block.","difficulty":"moderate","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-computer-networks-86","question":"A sender transmits bytes 1–4000 as four 1000-byte TCP segments. Segment 2 (bytes 1001–2000) is lost; segments 1, 3 and 4 arrive in order. Using cumulative acknowledgements (ACK = next byte expected), which ACK numbers does the receiver send?","options":["1001, 3001, 4001","1000, 1000, 1000","1001, 2001, 4001","1001, 1001, 1001"],"answer":3,"explanation":"After segment 1 the receiver expects byte 1001. Segments 3 and 4 are out of order, so each triggers a duplicate ACK for 1001. Two duplicates after the original ACK are what fast retransmit counts. 1000 forgets that the ACK names the NEXT byte expected.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-computer-networks-87","question":"A 1 MB file (take 1 MB = 10⁶ bytes) is sent in one burst over an 8 Mbps link with a one-way propagation delay of 20 ms. How long after the first bit is sent does the last bit arrive?","options":["1.02 s","1 s","0.145 s","1.04 s"],"answer":0,"explanation":"Transmission time = 8 × 10⁶ bits / 8 × 10⁶ bps = 1 s; the last bit then needs 20 ms to propagate: 1.02 s. 0.145 s treats MB as megabits; 1.04 s adds a round trip.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-computer-networks-88","question":"An organisation owns 172.20.0.0/16 and needs equal-sized subnets, each with at least 1000 usable host addresses. What is the maximum number of such subnets?","options":["32","64","128","16"],"answer":1,"explanation":"1000 hosts need 10 host bits (2¹⁰ − 2 = 1022; 9 bits give only 510). That makes each subnet a /22, and 16 − 10 = 6 bits are left for subnetting: 2⁶ = 64. 128 uses only 9 host bits.","difficulty":"hard","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-computer-networks-89","question":"An access-control list needs the wildcard mask that corresponds to the subnet mask 255.255.248.0. What is it?","options":["0.0.8.255","0.0.248.255","0.0.7.255","255.255.7.0"],"answer":2,"explanation":"A wildcard mask is the bitwise inverse of the subnet mask: 255 − each octet = 0.0.7.255. 0.0.8.255 is the block size, not its inverse.","difficulty":"moderate","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-computer-networks-90","question":"In distance-vector routing, which technique stops a router from advertising a route back out of the interface through which it learned that route?","options":["Route poisoning","Hold-down timer","Triggered update","Split horizon"],"answer":3,"explanation":"Split horizon suppresses advertising a route back towards the neighbour it came from, which breaks simple two-router loops. Route poisoning advertises a failed route with infinite metric; hold-down timers ignore new information briefly; triggered updates send changes immediately.","difficulty":"moderate","source":"Product-company interview pattern"},
  {"id":"cs-computer-networks-91","question":"An ISP wants to advertise the eight networks 192.168.4.0/24 through 192.168.11.0/24 with a single CIDR prefix. What is the smallest single prefix that covers all of them?","options":["192.168.0.0/20","192.168.4.0/21","192.168.8.0/21","192.168.4.0/22"],"answer":0,"explanation":"Eight /24s would fit a /21, but /21 blocks must start at a multiple of 8 in the third octet: 0–7 or 8–15. The range 4–11 crosses that boundary, so the smallest single block is 192.168.0.0/20 (third octet 0–15). 192.168.4.0/21 is not a valid network address.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-computer-networks-92","question":"You type https://shop.example.com into a browser that has nothing cached. In which order do these happen?\n1. TLS handshake\n2. DNS resolution\n3. HTTP GET request\n4. TCP three-way handshake","options":["2, 1, 4, 3","4, 2, 1, 3","2, 4, 3, 1","2, 4, 1, 3"],"answer":3,"explanation":"The browser first needs the IP address (DNS), then a TCP connection, then TLS on top of TCP, and only then sends the HTTP request inside the encrypted channel. TLS cannot start before TCP is established, and the GET must be encrypted, so it comes last.","difficulty":"moderate","source":"Product-company interview pattern"},
  {"id":"cs-computer-networks-93","question":"What is the shortest valid form of the IPv6 address 2001:0db8:0000:0000:0000:ff00:0042:8329?","options":["2001:db8::ff:42:8329","2001:db8::ff00:42:8329","2001:db8:0:0:0:ff00:42:8329:","2001:db8::ff00::42:8329"],"answer":1,"explanation":"Drop leading zeros in each group (0db8 → db8, 0042 → 42) and replace the single longest run of zero groups with ::. “ff00” keeps its trailing zeros; :: may appear only once, so the last option is invalid.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-computer-networks-94","question":"Starting from 172.16.32.0/23, subnets are allocated largest first, each at the next aligned boundary, for LANs needing 200, 100 and 50 hosts. What is the broadcast address of the 50-host subnet?","options":["172.16.33.127","172.16.32.255","172.16.33.191","172.16.33.255"],"answer":2,"explanation":"200 hosts → /24: 172.16.32.0/24. 100 hosts → /25: 172.16.33.0/25. 50 hosts → /26: 172.16.33.128/26, whose broadcast is 172.16.33.191. 172.16.33.127 is the broadcast of the 100-host subnet.","difficulty":"hard","source":"Wipro · Cognizant technical pattern"},
  {"id":"cs-computer-networks-95","question":"A web server listens on TCP port 443. Three browsers on the same client machine connect to it at the same time. How does the server’s operating system tell the three connections apart?","options":["By the 4-tuple (source IP, source port, destination IP, destination port); each browser connection uses a different source port","The server opens a new listening port for each connection","By the client’s MAC address in each frame","It cannot; only one connection per client IP is allowed"],"answer":0,"explanation":"A TCP connection is identified by its 4-tuple. All three share the server IP and port 443 and the client IP, but the client OS gives each an ephemeral source port. The listening port does not change, and MAC addresses do not survive routers.","difficulty":"hard","source":"Product-company interview pattern"},
  {"id":"cs-computer-networks-96","question":"A TCP sender has cwnd = 12 KB. The receiver last advertised a window of 8 KB, and 3 KB of data is already sent but not yet acknowledged. How much more new data may the sender transmit right now?","options":["9 KB","5 KB","8 KB","12 KB"],"answer":1,"explanation":"Effective window = min(cwnd, rwnd) = min(12, 8) = 8 KB. With 3 KB already in flight, 8 − 3 = 5 KB more can be sent. 9 KB uses cwnd and ignores the receiver’s limit.","difficulty":"hard","source":"Accenture · Capgemini technical pattern"},
  {"id":"cs-computer-networks-97","question":"For the host 200.1.1.100/28, what are the first and last usable host addresses of its subnet?","options":["200.1.1.96 and 200.1.1.111","200.1.1.97 and 200.1.1.111","200.1.1.97 and 200.1.1.110","200.1.1.101 and 200.1.1.114"],"answer":2,"explanation":"A /28 has blocks of 16: 96–111 contains 100. 96 is the network address and 111 the broadcast, so usable hosts are .97 to .110. The first option lists the network and broadcast addresses themselves.","difficulty":"moderate","source":"TCS NQT · Infosys interview pattern"},
  {"id":"cs-computer-networks-98","question":"A TCP Reno sender starts transmission round 1 with cwnd = 1 MSS and ssthresh = 32 MSS. In slow start cwnd doubles every round but is never raised above ssthresh; at or above ssthresh it grows by 1 MSS per round. A loss is detected by three duplicate ACKs during round 9 and by a timeout during round 15. On triple duplicate ACK, ssthresh = floor(cwnd/2) and the next round starts with cwnd = ssthresh; on timeout, ssthresh = floor(cwnd/2) and cwnd restarts at 1 MSS. What is cwnd in round 22?","options":["13 MSS","18 MSS","12 MSS","14 MSS"],"answer":0,"explanation":"Rounds 1-6: 1, 2, 4, 8, 16, 32 (slow start reaches ssthresh). Rounds 7-9: 33, 34, 35. Triple duplicate ACK at 35: ssthresh = 17, and rounds 10-15 are 17, 18, 19, 20, 21, 22. Timeout at 22: ssthresh = 11, cwnd = 1. Rounds 16-19: 1, 2, 4, 8. Doubling 8 would give 16, above ssthresh, so round 20 is 11, then 12 and 13 in rounds 21 and 22. The 18 MSS answer comes from letting slow start overshoot to 16 and then adding 1 per round; 12 is the value one round too early.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-99","question":"A TCP sender must deliver a file of exactly 100 segments. It starts with cwnd = 1 segment and ssthresh = 8 segments; cwnd doubles per round below ssthresh and grows by 1 per round from ssthresh onwards. The receiver advertises a constant window of 10 segments, there are no losses, and in each round the sender transmits min(cwnd, receiver window) segments. In which round is the last segment of the file sent?","options":["Round 12","Round 13","Round 7","Round 11"],"answer":1,"explanation":"Segments per round: 1, 2, 4, 8 (slow start), then 9, 10 in congestion avoidance. From round 7 onwards cwnd is 11 or more, but the receiver window caps each round at 10. Running total: 1, 3, 7, 15, 24, 34 after six rounds, then +10 per round: 44, 54, 64, 74, 84, 94, 104. The total first reaches 100 in round 13. Ignoring the receiver window gives round 12 (57, 70, 84, 99, 115); pure doubling with no threshold gives round 7.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-100","question":"A TCP sender has EstimatedRTT = 100 ms and DevRTT = 10 ms. Two new RTT samples arrive: 140 ms, then 80 ms. For each sample it first updates DevRTT = 0.75 x DevRTT + 0.25 x |Sample - EstimatedRTT| using the old EstimatedRTT, and then EstimatedRTT = 0.875 x EstimatedRTT + 0.125 x Sample. With timeout = EstimatedRTT + 4 x DevRTT, what is the retransmission timeout after the second sample?","options":["140.625 ms","172.5 ms","179.375 ms","181.875 ms"],"answer":2,"explanation":"Sample 140: DevRTT = 7.5 + 0.25 x 40 = 17.5; EstimatedRTT = 87.5 + 17.5 = 105. Sample 80: DevRTT = 13.125 + 0.25 x |80 - 105| = 13.125 + 6.25 = 19.375; EstimatedRTT = 91.875 + 10 = 101.875. Timeout = 101.875 + 4 x 19.375 = 179.375 ms. Updating EstimatedRTT before DevRTT gives 172.5 ms, which is not the order stated; adding only 2 x DevRTT gives 140.625 ms.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-101","question":"A client opens a TCP connection with initial sequence number 5000; the server chooses 9000. After the three-way handshake the client sends three data segments of 400, 300 and 500 bytes, the server replies with one segment of 700 bytes, and all data is acknowledged. The client then sends a FIN carrying no data. What are the sequence number and acknowledgment number in that FIN segment, and what acknowledgment number does the server use to acknowledge the FIN?","options":["FIN: seq 6201, ack 9700; server acknowledges 6202","FIN: seq 6200, ack 9700; server acknowledges 6201","FIN: seq 6201, ack 9701; server acknowledges 6201","FIN: seq 6201, ack 9701; server acknowledges 6202"],"answer":3,"explanation":"A SYN consumes one sequence number, so the client's first data byte is 5001 and the server's is 9001. After 400 + 300 + 500 = 1200 bytes the client's next sequence number is 6201, which the FIN uses. The server sent bytes 9001-9700, so the client acknowledges 9701. A FIN also consumes one sequence number, so the server acknowledges 6202. The answers with 6200 or 9700 forget that the SYN used a number; acknowledging 6201 forgets that the FIN does too.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-102","question":"Two stations 3000 km apart are joined by a 4 Mbps link on which signals travel at 2 x 10^8 m/s. Frames are 2000 bytes long, ACKs are negligibly short and there are no errors. With Go-Back-N and a sender window of 5 frames, what is the throughput?","options":["About 2.35 Mbps","About 0.47 Mbps","About 2.67 Mbps","4 Mbps"],"answer":0,"explanation":"Transmission time Tt = 16000 bits / 4 Mbps = 4 ms; propagation time Tp = 3000 km / (2 x 10^8 m/s) = 15 ms. One cycle is Tt + 2Tp = 34 ms, i.e. 1 + 2a = 8.5 frame times. In each cycle the sender can send only 5 frames, so utilisation = 5/8.5 = 0.588 and throughput = 0.588 x 4 = 2.35 Mbps. 0.47 Mbps is the stop-and-wait figure (1/8.5); 2.67 Mbps uses 1 + a instead of 1 + 2a; 4 Mbps would need a window of at least 9.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-103","question":"A stop-and-wait link runs at 1 Mbps with a one-way propagation delay of 10 ms. Data frames are 5000 bits, ACKs are 500 bits, and each data frame is lost independently with probability 0.2 (ACKs are never lost). The timeout is set exactly equal to the time of one successful send-and-acknowledge cycle. What is the expected throughput of data bits?","options":["About 196.1 kbps","About 156.9 kbps","160 kbps","800 kbps"],"answer":1,"explanation":"One cycle = frame 5 ms + propagation 10 ms + ACK 0.5 ms + propagation 10 ms = 25.5 ms, and a failed attempt costs the same because the timeout equals the cycle. Expected attempts per frame = 1/(1 - 0.2) = 1.25, so each frame takes 31.875 ms on average. Throughput = 5000 bits / 31.875 ms = 156.9 kbps. 196.1 kbps ignores the losses, 160 kbps ignores the ACK's transmission time, and 800 kbps is just 0.8 x the link rate.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-104","question":"A sender must deliver frames 1 to 12. Every 6th frame transmission (counting retransmissions too) is lost; ACKs are never lost. With Go-Back-N and window size 4, after a frame is lost the sender still transmits the following frames of its window (up to 3 more, if they exist) before it times out and goes back to the lost frame. With Selective Repeat only the lost frame is resent. How many frame transmissions are needed in total under Go-Back-N and under Selective Repeat?","options":["21 and 14","23 and 15","23 and 14","19 and 15"],"answer":2,"explanation":"Go-Back-N: transmissions 1-5 carry frames 1-5; the 6th (frame 6) is lost, then frames 7, 8, 9 are sent uselessly (transmissions 7-9). Go back: 6, 7, then frame 8 is the 12th transmission and is lost; 9, 10, 11 follow (13-15). Go back: 8, 9, then frame 10 is the 18th and is lost; 11, 12 follow (19, 20). Go back: 10, 11, 12 (21-23). Total 23. Selective Repeat: 12 frames plus one retransmission per loss; with 14 transmissions two (the 6th and 12th) are lost and 12 succeed, so 14. Counting 15 assumes a third loss that is never needed.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-105","question":"A stop-and-wait sender has 6 frames to deliver over a 100 kbps link with one-way propagation delay 20 ms. Frames are 1000 bits and ACKs are negligibly short. A 60 ms retransmission timer is started when the last bit of a frame leaves the sender. Every 3rd frame transmission (counting retransmissions) is lost; ACKs are never lost. How long after the start is the ACK of the sixth frame received?","options":["400 ms","300 ms","420 ms","440 ms"],"answer":3,"explanation":"Frame time = 1000/100 kbps = 10 ms. A successful transmission takes 10 + 2 x 20 = 50 ms; a lost one takes 10 + 60 = 70 ms before the retransmission starts. Six frames must succeed: of the first 8 transmissions the 3rd and 6th are lost and six succeed. Time = 6 x 50 + 2 x 70 = 440 ms. 300 ms ignores the losses; 420 ms starts the timer when the frame starts instead of when it ends; 400 ms treats a lost attempt as costing only 50 ms.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-106","question":"A 20 Mbps link has a one-way propagation delay of 8 ms and carries 1250-byte frames; ACKs are negligibly short. The sender window is chosen as the smallest size that keeps the link 100% utilised. What is the minimum number of sequence-number bits needed for Go-Back-N and for Selective Repeat (receiver window equal to sender window) respectively?","options":["6 bits and 7 bits","6 bits and 6 bits","5 bits and 6 bits","7 bits and 8 bits"],"answer":0,"explanation":"Tt = 10000 bits / 20 Mbps = 0.5 ms, so a = 8/0.5 = 16 and the window for full utilisation is 1 + 2a = 33 frames. Go-Back-N needs at least W + 1 = 34 sequence numbers, so 6 bits (64). Selective Repeat needs at least 2W = 66 sequence numbers, so 7 bits (128); 6 bits give only 64. Using a window of 1 + a = 17 leads to 5 and 6 bits, and forgetting the 2W rule gives 6 and 6.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-107","question":"An IPv4 datagram of total length 4020 bytes (20-byte header, no options) is forwarded over a link with MTU 1500 bytes and then over a link with MTU 620 bytes. Each router fragments whatever it receives into the largest fragments its outgoing link allows, and nothing is reassembled until the destination. How many fragments reach the destination, and what is the fragment-offset field of the one carrying the final bytes of the payload?","options":["7 fragments; offset 450","8 fragments; offset 445","8 fragments; offset 450","8 fragments; offset 3560"],"answer":1,"explanation":"MTU 1500 allows 1480 payload bytes: the 4000-byte payload becomes 1480 + 1480 + 1040 (offsets 0, 185, 370). MTU 620 allows 600 payload bytes: each 1480-byte fragment becomes 600 + 600 + 280 and the 1040-byte one becomes 600 + 440, giving 3 + 3 + 2 = 8 fragments. The last starts at payload byte 2960 + 600 = 3560, so its offset field is 3560/8 = 445 (length 440 + 20 = 460). Fragmenting the original directly at MTU 620 would give 7 fragments with last offset 450, but routers re-fragment the fragments they receive; 3560 is the byte position, not the field value in 8-byte units.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-108","question":"A router receives an IPv4 fragment with header length field 5, total length 1196, fragment offset 294 and the More Fragments bit set. Numbering the original datagram's payload bytes from 0, which bytes does this fragment carry, and what fragment-offset value will the next fragment of the same datagram have?","options":["Bytes 2352 to 3547; next offset 444","Bytes 294 to 1469; next offset 1470","Bytes 2352 to 3527; next offset 441","Bytes 2352 to 3527; next offset 442"],"answer":2,"explanation":"Header = 5 x 4 = 20 bytes, so the payload is 1196 - 20 = 1176 bytes. The offset is in units of 8 bytes: first byte = 294 x 8 = 2352, last byte = 2352 + 1176 - 1 = 3527. The next fragment starts at byte 3528, i.e. offset 3528/8 = 441. Treating the offset as a byte count gives 294 to 1469; using the total length 1196 as the payload gives 3547; 442 is an off-by-one, since 1176/8 = 147 exactly and 294 + 147 = 441.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-109","question":"A sender protects the 10-bit message 1011001110 with a CRC using the generator 10011 (x^4 + x + 1) and transmits the resulting 14-bit codeword. Each string below is a corrupted version of that codeword. Which one will the receiver's CRC check accept as error-free?","options":["10110011110100","10111010100101","10000111100101","10111010000101"],"answer":3,"explanation":"Dividing 10110011100000 by 10011 (modulo 2) leaves remainder 0101, so the codeword is 10110011100101. An error goes undetected only if the error pattern itself is divisible by the generator. 10111010000101 differs from the codeword in bit positions 5, 8 and 9 from the left, i.e. the error pattern is 10011 shifted - a multiple of the generator - so the remainder is still 0000. The others have error patterns with two bits, or a burst of at most 4 bits, which x^4 + x + 1 always detects (remainders 0110, 1100 and 0010).","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-110","question":"A 12-bit Hamming codeword protects 8 data bits. Positions are numbered 1 to 12 from the left, even-parity check bits sit at positions 1, 2, 4 and 8 (the check bit at position p covers every position whose binary number has bit p set), and data bits fill positions 3, 5, 6, 7, 9, 10, 11, 12 in order. The word 001001110000 is received with at most one bit in error. Which position is in error, and what 8 data bits were sent?","options":["Position 10; data 10110100","No data bit is wrong; data 10110000","Position 5; data 11110000","Position 12; data 10110001"],"answer":0,"explanation":"Recompute the four parity checks on 001001110000: check 1 (positions 1,3,5,7,9,11) is even, check 2 (2,3,6,7,10,11) is odd, check 4 (4,5,6,7,12) is even, check 8 (8,9,10,11,12) is odd. The failing checks sum to 2 + 8 = 10, so position 10 is wrong. Flipping it gives 001001110100, whose data bits (positions 3,5,6,7,9,10,11,12) are 10110100. Reading the syndrome bits in reverse order points to position 5, which is the trap; leaving the word uncorrected gives 10110000.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-111","question":"A 100 Mbps CSMA/CD network has its two farthest stations 500 m of cable apart, with two repeaters on the path between them. Signals travel at 2 x 10^8 m/s in the cable and each repeater adds a delay of 1 microsecond in each direction. What is the minimum frame size that guarantees a station is still transmitting when a collision reaches it?","options":["500 bits","900 bits","450 bits","700 bits"],"answer":1,"explanation":"One-way delay = 500/(2 x 10^8) s = 2.5 microseconds of cable + 2 x 1 microsecond of repeaters = 4.5 microseconds. The frame must last a full round trip, 9 microseconds, so it needs 9 x 10^-6 x 100 x 10^6 = 900 bits. 500 bits ignores the repeaters, 450 bits uses only the one-way delay, and 700 bits counts the repeater delay in one direction only.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-112","question":"Two Ethernet stations A and B collide. For A this is the 1st collision of its current frame, so it picks its backoff K uniformly from {0, 1}; for B it is the 3rd collision of its frame, so it picks K uniformly from {0, 1, ..., 7}. What is the probability that A picks a strictly smaller backoff than B and therefore transmits first?","options":["7/8","3/4","13/16","1/2"],"answer":2,"explanation":"There are 2 x 8 = 16 equally likely pairs. If A picks 0, B must pick 1-7: 7 pairs. If A picks 1, B must pick 2-7: 6 pairs. So P(A first) = 13/16. The remaining 3/16 splits into 2/16 for a repeat collision (equal picks) and 1/16 for B going first (A = 1, B = 0). 7/8 forgets the case where A picks 1; 1/2 wrongly treats the two stations as symmetric - binary exponential backoff favours the station with fewer collisions.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-113","question":"Routers A, B and C run a basic distance-vector protocol with no split horizon or poisoned reverse. Link costs are A-B = 3, B-C = 2 and A-C = 40, and the tables are stable (B reaches C at cost 2, A reaches C at cost 5 via B). The cost of link B-C now rises to 30. B recomputes first and advertises to A; from then on A and B alternately recompute and advertise whenever their distance to C changes. Counting every change of the distance-to-C entry at A or B (including B's first), how many changes occur before the tables are stable, and what are the final distances to C?","options":["8 changes; A = 29, B = 26","2 changes; A = 33, B = 30","10 changes; A = 40, B = 30","10 changes; A = 33, B = 30"],"answer":3,"explanation":"B still believes A can reach C at cost 5, so it picks min(30, 3 + 5) = 8 - a route that actually loops back through B. Then A: min(40, 3 + 8) = 11; B: 14; A: 17; B: 20; A: 23; B: 26; A: 29; B: min(30, 3 + 29) = 30; A: min(40, 3 + 30) = 33; B: min(30, 36) = 30, unchanged. B's entry took the values 8, 14, 20, 26, 30 and A's 11, 17, 23, 29, 33: 10 changes in all. Only 2 changes would be needed if B knew A's route went through B itself, which is what poisoned reverse provides. A does not end at 40 because 3 + 30 = 33 through B is cheaper than the direct link.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-114","question":"Five routers use distance-vector routing with link costs A-B = 1, B-C = 2, C-D = 1, D-E = 3, A-E = 12, A-D = 7 and B-D = 5. Initially each router knows only the costs of its own links. In each round all routers simultaneously send their current vectors to their neighbours and then all recompute. What is A's distance to E after exactly two rounds?","options":["9","10","7","12"],"answer":0,"explanation":"After r rounds a router knows the best path of at most r + 1 hops. Start: A-E = 12 (1 hop). After round 1 (2 hops): A-D-E = 7 + 3 = 10. After round 2 (3 hops): A-B-D-E = 1 + 5 + 3 = 9. Only after round 3 does A learn the true shortest path A-B-C-D-E = 1 + 2 + 1 + 3 = 7, which needs 4 hops. So after two rounds the entry is 9; 7 is the converged value, and 10 is the value one round earlier.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-115","question":"Dijkstra's algorithm is run from S on an undirected network with link costs S-A 7, S-B 2, S-C 6, A-B 3, B-D 8, A-D 4, B-C 5, C-E 5, D-E 1, D-F 6 and E-F 9. In what order are the nodes finalised, and what successive tentative labels does node E receive?","options":["S, B, A, C, D, E, F; E is labelled 10 only","S, B, A, C, D, E, F; E is labelled 11, then 10","S, B, C, A, D, E, F; E is labelled 11, then 10","S, B, A, D, C, E, F; E is labelled 10 only"],"answer":1,"explanation":"From S: A = 7, B = 2, C = 6. Finalise B (2): A improves to 5, D = 10, C stays 6 (2 + 5 = 7 is worse). Finalise A (5): D improves to 9. Finalise C (6): E = 11. Finalise D (9): E improves to 10, F = 15. Finalise E (10): F stays 15 (10 + 9 = 19). Finalise F (15). C (6) is finalised before D (9), so E is first labelled 11 through C and only later lowered to 10 through D. A (5) leaves the queue before C (6) because of the relaxation through B.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-116","question":"The block 10.20.64.0/20 is allocated with VLSM, always taking the lowest free addresses and handling requests in this order: LANs needing 900, 400, 200 and 100 hosts, then three point-to-point links needing 2 hosts each. Every subnet is the smallest that fits its need. Which subnet does the third point-to-point link receive, and how many addresses of the /20 are left unallocated?","options":["10.20.72.8/30; 2164 addresses","10.20.71.136/30; 2176 addresses","10.20.71.136/30; 2164 addresses","10.20.71.132/30; 2168 addresses"],"answer":2,"explanation":"900 hosts need a /22 (1022 usable): 10.20.64.0/22. 400 need a /23: 10.20.68.0/23. 200 need a /24: 10.20.70.0/24. 100 need a /25: 10.20.71.0/25. The links take /30s from 10.20.71.128: .128/30, .132/30 and .136/30. Allocated = 1024 + 512 + 256 + 128 + 3 x 4 = 1932 of 4096, leaving 2164. 2176 forgets the three /30s; 10.20.72.8/30 would follow only if the /25 had been rounded up to a /24; .132/30 is the second link, not the third.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-117","question":"A router uses longest-prefix matching with these entries: 10.4.0.0/14 -> interface A, 10.6.0.0/15 -> interface B, 10.6.128.0/17 -> interface C, 10.7.64.0/18 -> interface D. How many distinct destination IPv4 addresses are forwarded out of interface B?","options":["114688","131072","98304","81920"],"answer":3,"explanation":"10.6.0.0/15 covers 10.6.0.0-10.7.255.255, which is 2^17 = 131072 addresses. Two more specific entries lie inside it: 10.6.128.0/17 (2^15 = 32768 addresses) and 10.7.64.0/18 (2^14 = 16384 addresses), and a longer prefix always wins. So B gets 131072 - 32768 - 16384 = 81920. 131072 ignores both more-specific routes, and 98304 or 114688 subtract only one of them.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-118","question":"A site owns 172.18.72.0/22, 172.18.76.0/23 and 172.18.80.0/22 and wants to advertise them with one prefix. What is the smallest single prefix that covers all three, and how many addresses inside that prefix do NOT belong to any of the three networks?","options":["172.18.64.0/19; 5632 addresses","172.18.64.0/20; 1536 addresses","172.18.72.0/20; 1536 addresses","172.18.64.0/19; 2560 addresses"],"answer":0,"explanation":"The third octet runs from 72 (01001000) to 83 (01010011). These share only the leading bits 010, so the common prefix is 16 + 3 = 19 bits: 172.18.64.0/19, covering 64-95 in the third octet, 8192 addresses. The three networks hold 1024 + 512 + 1024 = 2560 addresses, so 8192 - 2560 = 5632 addresses are covered but not owned. A /20 starting at 64 stops at 79 and misses 172.18.80.0/22; 172.18.72.0/20 is not a valid block boundary; 2560 is the owned count, not the excess.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-119","question":"From the block 192.168.0.0/22, three subnets have already been assigned: 192.168.1.64/26, 192.168.2.0/25 and 192.168.3.240/28. How many /27 subnets of the block are still completely free (overlapping none of the assigned ranges)?","options":["26","25","24","28"],"answer":1,"explanation":"A /22 contains 2^(27-22) = 32 subnets of size /27 (32 addresses each). The /26 (64 addresses) occupies 2 of them, the /25 (128 addresses) occupies 4, and the /28 (16 addresses) spoils 1 more, because the /27 192.168.3.224/27 that contains it is no longer completely free. 32 - 2 - 4 - 1 = 25. Answering 26 forgets that a partly used /27 cannot be handed out.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-120","question":"Host X sends 10 packets of 1000 bytes each to host Y through two store-and-forward routers. The three links on the path have rates 2 Mbps, 1 Mbps and 4 Mbps in that order. X transmits the packets back to back starting at t = 0; propagation and processing delays are negligible and queues never overflow. At what time has Y completely received the last packet?","options":["50 ms","140 ms","86 ms","82 ms"],"answer":2,"explanation":"Each packet is 8000 bits, so it takes 4 ms, 8 ms and 2 ms on the three links. The first packet finishes the second link at 4 + 8 = 12 ms. That link is the bottleneck: packets arrive every 4 ms but leave every 8 ms, so packet 10 finishes it at 12 + 9 x 8 = 84 ms and reaches Y after 2 ms more, at 86 ms. 140 ms wrongly sends packets one at a time end to end (10 x 14 ms); 50 ms assumes the first link sets the pace (10 x 4 + 8 + 2).","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-121","question":"A 4800-byte message is sent over a path of 4 store-and-forward links of equal rate (3 routers), with negligible propagation delay. The message is cut into equal packets, each carrying p bytes of data plus a 20-byte header, and the packets are sent back to back. Which of these values of p delivers the whole message soonest?","options":["p = 120 bytes","p = 1200 bytes","p = 480 bytes","p = 240 bytes"],"answer":3,"explanation":"With N packets over k links, the last packet arrives after (N + k - 1) packet transmission times, so the delay is proportional to (4800/p + 3) x (p + 20) byte-times. p = 1200: 7 x 1220 = 8540. p = 480: 13 x 500 = 6500. p = 240: 23 x 260 = 5980. p = 120: 43 x 140 = 6020. So 240 bytes is best: larger packets waste time being stored and forwarded whole at each hop, while at 120 bytes the header overhead starts to dominate.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-122","question":"A host is shaped by a token bucket of capacity 6 Mb that fills at 4 Mbps; the bucket is full at t = 0. The output link can carry at most 10 Mbps. A burst of 20 Mb of data becomes ready at t = 0. How long does it take to send the whole burst?","options":["3.5 s","5 s","2 s","2.5 s"],"answer":0,"explanation":"While tokens remain, the host sends at the 10 Mbps peak while tokens arrive at 4 Mbps, so the bucket drains at 6 Mbps and lasts S = 6/(10 - 4) = 1 s, in which 10 Mb are sent. The remaining 10 Mb can go only at the token rate of 4 Mbps, taking 2.5 s. Total 3.5 s. 5 s ignores the stored tokens (20/4), 2 s ignores the shaper altogether (20/10), and 2.5 s is only the second phase.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-123","question":"Stations sharing a 56 kbps pure ALOHA channel send 1000-bit frames. Together (new frames plus retransmissions) they attempt 28 frames per second, with attempts forming a Poisson process. How many frames per second get through successfully?","options":["About 17.0 frames/s","About 10.3 frames/s","28 frames/s","About 5.2 frames/s"],"answer":1,"explanation":"Frame time = 1000/56000 s, so the channel can carry 56 frames per second and the offered load is G = 28/56 = 0.5 frames per frame time. Pure ALOHA throughput is S = G x e^(-2G) = 0.5 x e^(-1) = 0.184 per frame time, i.e. 0.184 x 56 = 10.3 frames/s. 17.0 uses the slotted ALOHA formula G x e^(-G); 28 assumes no collisions at all.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-124","question":"An HDLC-style link uses the flag 01111110 and bit stuffing: the sender inserts a 0 after every run of five consecutive 1s in the data. The 27-bit data field 011111011111101111110011111 is to be sent. How many bits are transmitted between the opening and closing flags?","options":["29 bits","30 bits","31 bits","28 bits"],"answer":2,"explanation":"A 0 is stuffed after every five consecutive 1s, whatever the next data bit is. The data has runs of 5, 6, 6 and 5 ones. Each run gets exactly one stuffed 0 (in a run of six, the count restarts after the stuffed 0, and the single remaining 1 does not reach five). That is 4 stuffed bits: 0111110011111010111110100111110, so 27 + 4 = 31 bits. Stuffing only where a sixth 1 actually follows gives 29; skipping the run at the very end gives 30 - but without that last 0, the data's final 11111 followed by the flag's leading 0 would be safe only by luck, and the rule is applied mechanically.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-125","question":"Hosts A, B, C, D and E are each attached to their own port of one Ethernet switch whose MAC table is empty. These frames are then sent in order (source -> destination): A -> B, B -> A, C -> A, D -> C, A -> E, E -> D, B -> E, and finally C sends a broadcast frame. How many of these eight frames are delivered to host D's port?","options":["5","3","2","4"],"answer":3,"explanation":"The switch learns the source of every frame and floods a frame only if the destination is unknown or broadcast. A -> B: B unknown, flooded (D sees it). B -> A and C -> A: A is known, forwarded only to A. D -> C: C is known, forwarded only to C. A -> E: E has not sent anything yet, so it is flooded (D sees it). E -> D: D is known, delivered to D. B -> E: E is now known, forwarded only to E. The broadcast from C reaches every port, including D. D's port therefore carries 4 frames: two unknown-unicast floods, one frame addressed to D, and the broadcast.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-126","question":"A leaky bucket holds at most 5 packets. In each clock tick, newly arrived packets are first placed in the bucket (those that do not fit are dropped), and then up to 2 packets are sent. The bucket starts empty and the arrivals in ticks 1 to 6 are 4, 5, 0, 6, 1 and 3 packets. After tick 6, how many packets have been dropped and how many are still waiting in the bucket?","options":["4 dropped; 3 waiting","2 dropped; 5 waiting","4 dropped; 5 waiting","7 dropped; 0 waiting"],"answer":0,"explanation":"Tick 1: 4 in, send 2, 2 left. Tick 2: 2 + 5 = 7, two dropped, 5 held, send 2, 3 left. Tick 3: no arrivals, send 2, 1 left. Tick 4: 1 + 6 = 7, two dropped, send 2, 3 left. Tick 5: 3 + 1 = 4, send 2, 2 left. Tick 6: 2 + 3 = 5 fits exactly, send 2, 3 left. Total dropped 4, with 3 waiting. Check: 19 arrived = 12 sent + 4 dropped + 3 waiting. Reporting 5 waiting forgets the send in tick 6.","difficulty":"very-hard","source":"Product company interview · GATE level"},
  {"id":"cs-computer-networks-127","question":"A browser with nothing cached fetches a page made of a base HTML file and 9 small images, all on one server. Resolving the server's name takes two DNS queries of 25 ms each. The round-trip time to the server is 40 ms and transmission times are negligible. The browser uses non-persistent HTTP and, after receiving the base file, opens at most 4 parallel TCP connections at a time. How long does it take to fetch the whole page?","options":["850 ms","370 ms","290 ms","170 ms"],"answer":1,"explanation":"DNS: 2 x 25 = 50 ms. Each non-persistent fetch costs 2 RTT = 80 ms (one RTT for the TCP handshake, one for the request and response). Base file: 80 ms. The 9 images need ceil(9/4) = 3 batches of parallel connections, each 80 ms: 240 ms. Total 50 + 80 + 240 = 370 ms. 850 ms fetches the images one after another (10 x 80 + 50); 290 ms assumes two batches are enough; 170 ms would need a persistent pipelined connection (50 + 80 + 40).","difficulty":"very-hard","source":"Product company interview · GATE level"},
];

export default questions;
